local KTool = CS.Engine.Lib.KTool
local UIModule = CS.Engine.UI.UIModule
---@type FishingUtils
local FishingUtils = import('Game.UI.Fishing.FishingUtils')
local fishingComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.FishingComponent)
local FishingMgr = import('Game.UI.Fishing.FishingMgr')
local ConstantsFishing = import('Game.UI.Fishing.ConstantsFishing')
local cardComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
local UIEventProxy = CS.Engine.UI.UIEventProxy
local cs_coroutine = import('XLua.cs_coroutine')
local WaitForSeconds = CS.UnityEngine.WaitForSeconds

----------------------------------------------------

---@class LeftPanelService
local LeftPanelService = Class("LeftPanelService")

function LeftPanelService.new(from)
    local obj = LeftPanelService.New()
    obj.luaDialog = from
    for k, v in pairs(from) do
        obj[k]=v
    end
    return obj
end

function LeftPanelService:UpdateInfo()
    local dojo = fishingComponent:GetFishingPlaceDojo(self.placeId)
    if not dojo then
        return
    end

    if checkNumber(dojo.partner) ~= 0 then
        local cardDojo = cardComponent:GetCardById(dojo.partner)
        if cardDojo then
            local vo = CardConfMgr:GetInstance():GetCardSkinBySkinId(cardDojo.cardSkin)
            if vo then
                CfUtils.FillImage(self.ImgHead, vo.buffHead)
                KTool.SetActive(self.StatusRoleHead, true)
            end
        end
    else
        KTool.SetActive(self.StatusRoleHead, false)
    end
end

function LeftPanelService:ShowMe()
    self:UpdateInfo()
    self:SetBtnActive(true)
    CfUtils.PlayAnimator(self.Root, "Show")
end

function LeftPanelService:BackMe()
    self:UpdateInfo()
    self:SetBtnActive(true)
    CfUtils.PlayAnimator(self.Root, "Back")
end

function LeftPanelService:HideMe()
    self:SetBtnActive(false)
    CfUtils.PlayAnimator(self.Root, "Out")
end

function LeftPanelService:SetBtnActive(flag)
    if flag then
        SetButtonAction(self.BtnAccompanyFishing, Bind(self, self.OnClick))
    else
        SetButtonAction(self.BtnAccompanyFishing, nil)
    end
end

function LeftPanelService:IsBlockClick(isBlock)
    local canvasGroup = KTool.GetOrAddComponent(self.LeftPanel.gameObject, typeof(CS.UnityEngine.CanvasGroup))
    canvasGroup.blocksRaycasts = not isBlock
end

function LeftPanelService:OnClick()
    if FishingUtils.IsAutoing() then
        return
    end
    UIModule.OpenDialog({id = Constants.UITypeIds.UIFightTeamCardChoose, parameters = {chooseCardStatu = Constants.ChooseCardStatus.FishAccompany, placeId = self.placeId}}, {
        { id = Constants.UITypeIds.UIFishPoolGoFishingDialog}
    })
end

function LeftPanelService:FishResultRoleTalk(params)
    self.luaDialog.CoTalk = cs_coroutine.start(function()
        self:BackMe()
        self:RefreshRoleTalk(params.type, params.fishId)
        cs_coroutine.yield_return(WaitForSeconds(FishingUtils.GetTalkTime()))
        self:RefreshRoleTalkIdle()
        self.CoTalk = nil
    end)
end

function LeftPanelService:RefreshRoleTalkIdle()
    local mgc = self.TextCardBuff.gameObject:GetComponent(typeof(CS.Game.Native.Common.MultiplyGradientColor2))
    if mgc then
        mgc.StartPos = -1
        mgc.EndPos = -1
    end

    local dojo = fishingComponent:GetFishingPlaceDojo(self.placeId)
    if not dojo then
        return
    end
    local cardDojo = cardComponent:GetCardById(dojo.partner)
    if not cardDojo then
        KTool.SetActive(self.Dialogue2, false)
        return
    end

    local str = ""
    local t = FishingUtils.GetFishCardBuffData(cardDojo.cardId, Constants.ChooseCardStatus.FishAccompany)
    if t then
        for k, v in pairs(t) do
            if checkNumber(cardDojo.star) >= checkNumber(v.starKey) then
                str = str..FishingUtils.GetAdditionDesc(v.buffData).."\n"
            end
        end
    end

    if string.isEmpty(str) then
        KTool.SetActive(self.Dialogue2, false)
        return
    end

    CfUtils.FillText(self.TextCardBuff, str)
    KTool.SetActive(self.Dialogue2, true)
end

function LeftPanelService:RefreshRoleTalk(type, para)
    local mgc = self.TextCardBuff.gameObject:GetComponent(typeof(CS.Game.Native.Common.MultiplyGradientColor2))
    if mgc then
        mgc.StartPos = -1
        mgc.EndPos = -1
    end

    local dojo = fishingComponent:GetFishingPlaceDojo(self.placeId)
    if not dojo then
        return
    end
    local cardDojo = cardComponent:GetCardById(dojo.partner)
    if not cardDojo then
        KTool.SetActive(self.Dialogue2, false)
        return
    end

    local str = ""
    if checkNumber(type) > 0 then
        local vo = CardConfMgr:GetInstance():GetCardByRefId(cardDojo.cardId)
        if vo then
            local talkId = FishingUtils.GetTalkIds(type, vo.characterId)
            local talkVo = FishingUtils.GetFishingTalkVo(talkId)
            if isNull(talkVo) then
                KTool.SetActive(self.Dialogue2, false)
                return
            end
            local fishVo = GoodsConfMgr:GetInstance():GetGoodsVoById(para)
            if (checkNumber(talkVo.condition) == ConstantsFishing.TalkType.FishFailBreakFree or
                    checkNumber(talkVo.condition) == ConstantsFishing.TalkType.FishFailBreakLine or
                    checkNumber(talkVo.condition) == ConstantsFishing.TalkType.FishFailDisOut) and
                    checkNumber(fishVo.quality) == 6 then
                str = talkVo.content
                local sT = CfUtils.Split(str, "_fishName_")
                local f = utf8.len(sT[1])
                if mgc then
                    mgc.StartPos = f
                    mgc.EndPos = f + utf8.len(fishVo.name) - 1
                end
                str = string.fmt(str, {_fishName_ = fishVo.name})
            else
                str = FishingUtils.GetTalkStrById(talkId, para)
            end

            KTool.SetActive(self.Dialogue2, true)
            self._talkTime = 0
        end
    else
        KTool.SetActive(self.Dialogue2, false)
    end
    CfUtils.FillText(self.TextCardBuff, str)
end

return LeftPanelService